class User {}

class Subscriber extends User {}

class MovieShop {
  + listMovies()
  + order()
  + subscribe()
}

class Card {}

class Order {}

class Movie {}

class MovieRent extends Movie {}

class MovieBuy extends Movie {}

enum MovieType {
  DVD
  VHS
}

enum MovieRentStatus {
  in
  out
}

enum MovieBuyStatus {
  present
  to order
}

User "*" --> "1" MovieShop : uses
MovieShop "1" -- "*" Card : make
MovieShop "1" --> "*" Order : make
Subscriber "1" --> "1" Card : has
MovieShop "1" o-- "*" Movie
Order "*" -- "1..*" MovieBuy : related to
Subscriber "*" --> "1..*" MovieRent : hire
User --> "1..*" MovieBuy

@enduml

